<script setup lang="ts">
import { computed, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useWorkspace } from './useWorkspace'
import ConversationSidebar from './components/ConversationSidebar.vue'
import MessageTimeline from './components/MessageTimeline.vue'
import Composer from './components/Composer.vue'
import EvidencePanel from './components/EvidencePanel.vue'
const { session, conversations, activeConversation, evidence, draft, input, turnStatus, clarification, connectionState, loading, unavailable, error, busy, canCopy, loadWorkspace, newConversation, selectConversation, send, stop, copyDraft, clearTurnState } = useWorkspace()
const route = useRoute()
const router = useRouter()
const reloadWorkspace = () => loadWorkspace(typeof route.params.conversation_id === 'string' ? route.params.conversation_id : undefined)
async function createConversation() { await newConversation(); if (activeConversation.value) await router.replace(`/chat/${activeConversation.value.id}`) }
async function openConversation(item: Parameters<typeof selectConversation>[0]) { await selectConversation(item); if (activeConversation.value) await router.replace(`/chat/${activeConversation.value.id}`) }
const connected = computed(() => connectionState.value === 'connected')
const connectionLabel = computed(() => ({ idle: '未连接', connecting: '连接中', connected: '已连接', reconnecting: '重连中', disconnected: '已断开' }[connectionState.value]))
onMounted(reloadWorkspace)
onUnmounted(clearTurnState)
</script>
<template>
<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">ER</span><div><strong>客服工作台</strong><small>Evidence-backed support</small></div></div><div class="top-meta" v-if="session"><span class="status-dot" :class="{ live: connected }"></span>{{ connectionLabel }} · {{ session.shopName }}<span class="user">{{ session.displayName }}</span></div></header>
<div v-if="loading" class="workspace-state panel"><strong>正在连接工作台…</strong><span>正在读取会话和权限范围</span></div><div v-else-if="unavailable" class="workspace-state panel"><strong>工作台暂不可用</strong><span>{{ error }}</span><button class="send-btn" type="button" @click="reloadWorkspace">重试</button></div>
<div class="workspace"><ConversationSidebar :items="conversations" :selected-id="activeConversation?.id" :shop-name="session?.shopName" :role="session?.role" @new="createConversation" @select="openConversation" />
<main class="chat panel"><div class="chat-heading"><div><p class="kicker">ASSISTED REPLY</p><h1>{{ activeConversation?.title ?? '新会话' }}</h1></div><span class="env-badge">M1 MOCK</span></div><div v-if="clarification" class="clarification-card"><strong>需要补充信息</strong><span>{{ clarification }}</span></div><MessageTimeline :messages="activeConversation?.messages ?? []" :busy="busy" :turn-status="turnStatus" /><div v-if="error" class="error-banner">{{ error }}</div><Composer v-model="input" :busy="busy" @send="send" @stop="stop" /></main>
<EvidencePanel :evidence="evidence" :draft="draft" /></div></div>
</template>
